class Solution { public long maxProduct(String s){int n=s.length();int[] radius=new int[n];for(int i=0,left=0,right=-1;i<n;i++){int value=i>right?1:Math.min(radius[left+right-i],right-i+1);while(i-value>=0&&i+value<n&&s.charAt(i-value)==s.charAt(i+value))value++;radius[i]=value;if(i+value-1>right){left=i-value+1;right=i+value-1;}}int[] end=new int[n],start=new int[n];for(int i=0;i<n;i++){int length=2*radius[i]-1;end[i+radius[i]-1]=Math.max(end[i+radius[i]-1],length);start[i-radius[i]+1]=Math.max(start[i-radius[i]+1],length);}for(int i=n-2;i>=0;i--)end[i]=Math.max(end[i],end[i+1]-2);for(int i=1;i<n;i++)end[i]=Math.max(end[i],end[i-1]);for(int i=1;i<n;i++)start[i]=Math.max(start[i],start[i-1]-2);for(int i=n-2;i>=0;i--)start[i]=Math.max(start[i],start[i+1]);long answer=0;for(int i=0;i+1<n;i++)answer=Math.max(answer,(long)end[i]*start[i+1]);return answer;} }
